sys_script_include.script:
var tesUtils = Class.create();
tesUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    copyQuestion: (question_id) => {
        let current = new GlideRecord('x_842748_tes_lore_tes_question');
        if (current.get(question_id)) {
            let newQuestion = new GlideRecord('x_842748_tes_lore_tes_question');
            newQuestion.initialize();
            newQuestion.setValue('type', current.getValue('type'));
            newQuestion.setValue('order', current.getValue('order'));
            newQuestion.setValue('mandatory', current.getValue('mandatory'));
            newQuestion.setValue('version', new x_842748_tes_lore.tesUtils().generateVersion(current.version.version + 1));
            newQuestion.setValue('book', current.getValue('book'));
            newQuestion.setValue('question_text', current.getValue('question_text'));
            newQuestion.setValue('question_id', current.getValue('question_id'));

            current.update();
            return newQuestion.insert();
        }
        return null;
    },

    generateVersion: (number) => {
        let version = new GlideRecord('x_842748_tes_lore_version');
        version.initialize();
        version.setValue('question', current.getUniqueValue());
        version.setValue('modified_by', gs.getUserID());
        version.setValue('modified_on', new GlideDateTime());
        version.setValue('version', number);
        return version.insert();
    },

    generateQuestions: function(questionnaire, game) {
        let question = new GlideRecord('x_842748_tes_lore_tes_question');
        question.addEncodedQuery('active=true^state=Published^book=' + game);
        question.orderBy('order');
        question.query();

        while (question.next()) {
            let answer = new GlideRecord('question_answer');
            answer.initialize();
            answer.table_name = questionnaire.getTableName();
            answer.table_sys_id = questionnaire.getUniqueValue();
            answer.question = question.getUniqueValue();
            answer.order = this._getNextOrder(questionnaire) + 100;
            answer.insert();
        }
    },

    _getNextOrder: function(questionnaire) {
        let questionAnswer = new GlideAggregate('question_answer');
        questionAnswer.addEncodedQuery('table_name=' + questionnaire.getTableName() + '^table_sys_id=' + questionnaire.getUniqueValue());
        questionAnswer.orderByDesc('order');
        questionAnswer.query();

        if (questionAnswer.next()) {
            return parseInt(questionAnswer.getValue('order'));
        }
        return 100;
    },

    skipGameFilter: (question_game) => {
        let availableGames = [];

        let game = new GlideRecord('x_842748_tes_lore_game');
        game.addEncodedQuery('active=true^initial_game=false');
        game.query();

        while (game.next()) {
            if (game.getUniqueValue() != question_game) {
                availableGames.push(game.getUniqueValue());
            }
        }

        return "sys_idIN" + availableGames.join(',');
    },

    type: 'tesUtils'
});
